mapper.update:
UPDATE ct_health_report_task
SET status = #{nextStatus},
    stage = #{stage},
    progress = #{progress},
    version = version + 1,
    update_by = #{updateBy}
WHERE task_id = #{taskId}
  AND status = #{expectedStatus}
  AND deleted_at IS NULL

UPDATE ct_health_report_task
SET status = 'FAILED',
    fail_code = 'EXECUTION_TIMEOUT',
    reanalyzable = 1,
    version = version + 1,
    update_by = #{updateBy}
WHERE task_id = #{taskId}
  AND status = 'ASSEMBLING'
  AND deleted_at IS NULL
  AND deadline_at < #{currentTime}

UPDATE ct_health_report_task
SET deleted_at = CURRENT_TIMESTAMP,
    version = version + 1,
    update_by = #{updateBy}
WHERE task_id = #{taskId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
